            rhs = x**2 * y**2 * z**2
            if lhs == rhs:
                solutions.append((x, y, z))
                print(f"Solution found: ({x}, {y}, {z})")

if not solutions:
    print("No solutions found in the given range.")
else:
    print(f"Total solutions found: {len(solutions)}")
    # Print solutions again for easy extraction
    for sol in solutions:
        print(sol)

def check_solution(x, y, z):
    lhs = x**3 + y**3 + z**3
    rhs = x**2 * y**2 * z**2
    return lhs == rhs

solutions = []
# Search up to x=3, y=4, z=5
for x in range(1, 4):
    for y in range(x, 5):
        for z in range(y, 6):
            if check_solution(x, y, z):
                solutions.append((x, y, z))

print(f"Solutions found in the range x<=3, y<=4, z<=5: {solutions}")
